+    assert_eq!(filled.openings, 1);
+    let deep = |t: &Toolpath| {
+        tips(t).into_iter().any(|q| (q.x - 10.0).abs() < 4.0 && (q.y - 10.0).abs() < 4.0 && q.z < TOP - 1.0)
